-- Validated in disposable MySQL8.4.11 Testcontainers. 전용 빈 로컬 합성DB에만 사용. 기존 개발/운영 DB에서 실행하지 말 것.
-- 먼저 현재 앱 Flyway V18까지 적용. no DROP/TRUNCATE/UPDATE existing business data.
-- Safety guard: only the dedicated evaluation DB or disposable Testcontainers DB, with no business rows.
-- mysql batch must run without --force; stop immediately on any SQL error.
DROP TEMPORARY TABLE IF EXISTS ai_eval_safety_guard;
CREATE TEMPORARY TABLE ai_eval_safety_guard (safe TINYINT NOT NULL CHECK (safe = 1));
SELECT IF(DATABASE() IN ('setty_ai_eval','setty_test')
          AND (SELECT COUNT(*) FROM members)=0
          AND (SELECT COUNT(*) FROM orders)=0
          AND (SELECT COUNT(*) FROM listings)=0
          AND (SELECT COUNT(*) FROM delivery)=0,1,0);
DROP TEMPORARY TABLE ai_eval_safety_guard;
SET time_zone = '+00:00';
SET @kst_today = DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+09:00'));
SET @yesterday_start = TIMESTAMP(@kst_today) - INTERVAL 1 DAY - INTERVAL 9 HOUR;
START TRANSACTION;
-- RegisterDeliveryService creates REQUESTED before inserting a delivery. Preserve that invariant:
-- otherwise cancellation incorrectly takes the pre-registration cancellation branch.
SELECT order_id,'REQUESTED',requested_at FROM delivery;
COMMIT;
-- E11 각 반복 전 reset: UPDATE delivery SET status='REQUESTED',accepted_at=NULL WHERE order_id=930013;
-- E11 중간 전환: UPDATE delivery SET status='ACCEPTED',accepted_at=UTC_TIMESTAMP(6) WHERE order_id=930013;
